import { useId, useLayoutEffect, useRef, useState, type KeyboardEvent, type ReactNode } from "react";
import { isClosedQuest, namesLabel, needsQuestAttention, statusLabel } from "./presentation";

type Row = Record<string, unknown>;

export interface WorkspaceQuest {
  id: string;
  title: string;
  status: string;
  version: number;
  goal: string;
  project_id?: string;
  project_name?: string;
  project_root?: string;
  workspace_id?: string;
  workspace_root?: string;
  metadata?: Row;
}

export interface QuestWorkspaceProps {
  quests: WorkspaceQuest[];
  selected: WorkspaceQuest | null;
  selectedId: string;
  connected: boolean;
  error: string;
  hasMore: boolean;
  onSelect: (id: string) => void;
  onLoadMore: () => void;
  plan: Row | null;
  planNotice: ReactNode;
  blocked: boolean;
  onApprove: () => void;
  grants: ReactNode;
  workspaceId?: string;
  workspaceRoot?: string;
  workspaceName?: string;
}

const text = (value: unknown, fallback = "未知"): string => value == null || value === "" ? fallback : String(value);
const records = (value: unknown): Row[] => Array.isArray(value)
  ? value.filter((item): item is Row => !!item && typeof item === "object" && !Array.isArray(item)) : [];
type QuestFilter = "all" | "active" | "attention" | "closed";
const QUEST_FILTERS: { id: QuestFilter; label: string }[] = [
  { id: "all", label: "全部" }, { id: "active", label: "未结束" },
  { id: "attention", label: "需处理" }, { id: "closed", label: "已结束" },
];

const QUEST_PHASES: Record<string, string> = {
  proposed: "目标已提出，后续计划与团队仍以实际提案为准。",
  awaiting_approval: "任务正在等待批准。请核对计划、任务团队及审批中心中需要确认的内容。",
  approved: "任务已批准；执行仍需满足当前计划、团队、工具权限与预算约束。",
  queued: "任务已进入队列，等待满足资源与执行条件。",
  running: "任务处于运行阶段。运行活动中可查看已记录的成员执行情况。",
  blocked: "任务已阻塞。请结合运行活动、审批与权限记录核对原因。",
  paused: "任务已暂停，当前记录保留在此工作空间。",
  needs_input: "任务需要补充信息，请回到长期对话继续说明。",
  reviewing: "任务正在复核。请以验证与最终任务状态判断结果。",
  completed: "任务状态为已完成，可通过计划与运行活动回查执行和验证记录。",
  failed: "任务已失败。请查看运行活动，并在长期对话中讨论后续处理。",
  cancelled: "任务已取消，历史计划与执行记录仍可回查。",
  rejected: "任务已拒绝，可查看历史计划与审批记录了解处理经过。",
};

function costLimit(plan: Row): string {
  if (plan.max_cost_microunits === null) return "未设置";
  if (plan.max_cost_microunits === undefined) return "未知";
  return `${text(plan.max_cost_microunits)} 微单位 · ${text(plan.cost_currency, "币种未知")}`;
}

function criteria(value: unknown): string {
  return Array.isArray(value) ? value.map((item) => text(item)).join("；") || "未提供" : text(value, "未提供");
}

interface QuestProject { key: string; name: string; path: string; quests: WorkspaceQuest[]; loaded: number }
const nonempty = (value: unknown): string => typeof value === "string" ? value.trim() : "";
const directoryName = (path: string): string => path.replace(/[\\/]+$/, "").split(/[\\/]/).pop() || "";
const pathIdentity = (path: string): string => {
  const normalized = path.replace(/\\/g, "/").replace(/\/+$/, "");
  return /^(?:[a-z]:\/|\/\/)/i.test(normalized) ? normalized.toLocaleLowerCase() : normalized;
};
const explicitProjectName = (quest: WorkspaceQuest): string => {
  const metadata = quest.metadata || {};
  const project = metadata.project && typeof metadata.project === "object" && !Array.isArray(metadata.project) ? metadata.project as Row : {};
  return nonempty(quest.project_name) || nonempty(metadata.project_name) || nonempty(project.name);
};
function projectFor(quest: WorkspaceQuest, workspaceId: string, workspaceRoot: string, workspaceName: string): Omit<QuestProject, "quests" | "loaded"> {
  const metadata = quest.metadata || {};
  const project = metadata.project && typeof metadata.project === "object" && !Array.isArray(metadata.project) ? metadata.project as Row : {};
  const projectId = nonempty(quest.project_id) || nonempty(metadata.project_id) || nonempty(project.id);
  const explicitRoot = nonempty(quest.project_root) || nonempty(metadata.project_root) || nonempty(project.root);
  const explicitWorkspaceId = nonempty(quest.workspace_id) || nonempty(metadata.workspace_id);
  const explicitWorkspaceRoot = nonempty(quest.workspace_root) || nonempty(metadata.workspace_root);
  const path = explicitRoot || explicitWorkspaceRoot || (!projectId && (!explicitWorkspaceId || explicitWorkspaceId === workspaceId) ? workspaceRoot : "");
  const name = explicitProjectName(quest) || directoryName(path) || projectId || explicitWorkspaceId || workspaceName || "当前工作空间";
  const currentKey = `workspace:${workspaceId || pathIdentity(workspaceRoot) || "current"}`;
  const sameWorkspace = !projectId && (explicitWorkspaceId && explicitWorkspaceId === workspaceId || path && workspaceRoot && pathIdentity(path) === pathIdentity(workspaceRoot));
  const key = projectId ? `project:${projectId}` : sameWorkspace ? currentKey : explicitRoot ? `root:${pathIdentity(explicitRoot)}` : explicitWorkspaceId ? `workspace:${explicitWorkspaceId}` : explicitWorkspaceRoot ? `root:${pathIdentity(explicitWorkspaceRoot)}` : currentKey;
  return { key, name, path };
